'use strict';
// Course data and teaching interactions are preserved from the supplied IASD HTML.
const C=JSON.parse(document.getElementById('course-data').textContent),KEY='hicall-iasd-studio-'+C.version;
const supplements=JSON.parse(document.getElementById('supplement-data')?.textContent||'{}');
function supplementHTML(kind){
  const s=supplements[view];if(!s)return '';
  if(kind==='concept')return `<details class="panel" data-iasd-supplement="${view}"><summary>Contoh kerja tambahan: ${esc(s.title)}</summary><p class="small">${esc(s.basis)}</p><h3>Input dan asumsi</h3><p>${esc(s.inputs)}</p><h3>Jejak penalaran</h3><ol>${s.reasoning.map(t=>`<li>${esc(t)}</li>`).join('')}</ol><h3>Hasil dan batas bukti</h3><p>${esc(s.result)}</p><p><b>Miskonsepsi dan koreksi:</b> ${esc(s.misconception)}</p></details>`;
  if(kind==='reflect')return `<section class="panel" data-iasd-transfer="${view}"><h3>Transfer individu tambahan</h3><p>${esc(s.transfer)}</p><p>${esc(s.artifact)}</p></section>`;
  if(kind==='teach')return `<details class="panel" data-iasd-facilitation="${view}"><summary>Fasilitasi tambahan: ${esc(s.title)}</summary><ol>${s.instructor.map(t=>`<li>${esc(t)}</li>`).join('')}</ol><p>${esc(s.rubric)}</p></details>`;
  return '';
}
const sessionNumber=value=>{const n=Number(value);return Number.isFinite(n)?Math.max(1,Math.min(C.lessons.length,Math.floor(n)||1)):1;};
const instructorMode=new URLSearchParams(location.search).get('mode')==='teach';
const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let storageOK=true,view=sessionNumber(location.hash.slice(1)||new URLSearchParams(location.search).get('session')),tab=instructorMode?'teach':'concept',focus=false,timer=null,seconds=300;
let state={course:C.id,version:C.version,alias:'',lessons:{}};
try{const saved=localStorage.getItem(KEY);if(saved)state=validateState(JSON.parse(saved));}catch(e){storageOK=false;}
view=Math.max(1,Math.min(16,Math.floor(view)));
function validateState(x){
  const record=value=>value!==null&&typeof value==='object'&&!Array.isArray(value);
  if(!record(x)||x.course!==C.id||x.version!==C.version||!record(x.lessons))throw Error('Berkas bukan cadangan mata kuliah/versi ini.');
  const v={course:C.id,version:C.version,alias:String(x.alias||'').slice(0,80),lessons:{}};
  for(let n=1;n<=C.lessons.length;n++){
    if(!Object.hasOwn(x.lessons,n))continue;
    const r=x.lessons[n];if(!record(r))continue;
    const a={notes:[0,1,2].map(i=>String(r.notes?.[i]||'').slice(0,12000)),checks:{},answers:{},rubric:[0,1,2,3].map(i=>{const value=Number(r.rubric?.[i]);return Number.isFinite(value)?Math.max(0,Math.min(4,Math.round(value))):0;}),sim:{},used:r.used===true,complete:r.complete===true};
    for(let i=0;i<8;i++)a.checks[i]=r.checks?.[i]===true;
    for(let i=0;i<3;i++)if(Number.isInteger(r.answers?.[i])&&r.answers[i]>=0&&r.answers[i]<3)a.answers[i]=r.answers[i];
    if(r.checked===true)a.checked=true;
    for(const[k,y]of Object.entries(record(r.sim)?r.sim:{})){
      if(!/^[a-zA-Z][a-zA-Z0-9_]{0,35}$/.test(k)||['constructor','prototype'].includes(k))continue;
      if(k==='log'){if(Array.isArray(y))a.sim.log=y.slice(-6).map(z=>String(z).slice(0,300));continue;}
      if(typeof y==='boolean'||(typeof y==='number'&&Number.isFinite(y)))a.sim[k]=y;
      if(typeof y==='string')a.sim[k]=y.slice(0,1000);
    }
    v.lessons[n]=a;
  }
  return v;
}
function rec(n=view){return state.lessons[n]||(state.lessons[n]={notes:['','',''],checks:{},answers:{},rubric:[0,0,0,0],sim:{},used:false,complete:false});}
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));}catch(e){storageOK=false;const w=$('#storage-warning');if(w){w.hidden=false;w.textContent='Penyimpanan browser tidak tersedia. Ekspor cadangan JSON sebelum menutup modul.';}}if($('#completed-count'))$('#completed-count').textContent=progress()+' / 16';if($('#completion-status'))$('#completion-status').textContent=rec().complete?'✓ Selesai sebagai latihan mandiri.':'Belum ditandai selesai.';if($('#lesson-list'))$('#lesson-list').innerHTML=nav($('#search')?.value||'');}
function toast(s){const t=$('#toast');t.textContent=s;t.classList.add('show');clearTimeout(toast.t);toast.t=setTimeout(()=>t.classList.remove('show'),4200);}
function download(name,text,type='text/plain;charset=utf-8'){const u=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=u;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),1500);}
const fmt=(n,d=2)=>Number.isFinite(n)?n.toLocaleString('id-ID',{maximumFractionDigits:d}):'Tidak terdefinisi';
const l=()=>C.lessons[view-1];
function csv(text){const lines=text.trim().split(/\r?\n/),heads=lines.shift().split(',');return lines.filter(Boolean).map(line=>Object.fromEntries(line.split(',').map((v,i)=>[heads[i],v])));}
const csvdata=name=>csv(C.files[name]||'');
function grade(n=view){const r=rec(n);return C.lessons[n-1].quiz.reduce((s,q,i)=>s+(r.answers[i]===q.answer?1:0),0);}
function progress(){return Object.values(state.lessons).filter(x=>x.complete).length;}
function heroArt(){return `<svg class="hero-art" viewBox="0 0 440 250" role="img" aria-label="Ilustrasi alur dari konsep menuju bukti pemahaman"><rect x="20" y="20" width="385" height="210" rx="24" fill="#e5eeef"/><circle cx="360" cy="58" r="38" fill="#e8c584"/><path d="M68 162L170 65L275 172L367 110" fill="none" stroke="#91b1b6" stroke-width="2" stroke-dasharray="6 6"/><rect x="50" y="100" width="100" height="74" rx="12" fill="#173d50"/><rect x="171" y="44" width="100" height="74" rx="12" fill="#087e80"/><rect x="287" y="133" width="100" height="74" rx="12" fill="#fff" stroke="#b9cdd0"/><text x="100" y="140" text-anchor="middle" fill="white" font-size="14">Konsep</text><text x="221" y="85" text-anchor="middle" fill="white" font-size="14">Eksperimen</text><text x="337" y="175" text-anchor="middle" fill="#173d50" font-size="14">Bukti</text><circle cx="170" cy="170" r="24" fill="#fff"/><path d="M158 171L167 180L184 160" fill="none" stroke="#087e80" stroke-width="4"/></svg>`;}
function app(){
  const item=l();document.title=`S${String(view).padStart(2,'0')} ${item.title} · ${C.title}`;
  $('#app').innerHTML=`<div class="layout"><aside class="side" aria-label="Navigasi pertemuan">
    <p class="brand">HAIKAL SHIDDIQ · IASD</p><h2>Analisis & desain sistem</h2>
    <p class="meta">SI306 · ${C.sks} SKS<br>16 pertemuan · ${C.minutes} menit reguler</p>
    <a class="side-home" href="/iasd">Peta belajar & cara pakai</a>
    <div class="desktop-sessions"><label class="small" for="search">Cari topik atau CPMK</label><input id="search" type="search" placeholder="Contoh: stok, CPMK2…" autocomplete="off"><nav class="nav-scroll" id="lesson-list">${nav()}</nav></div>
  </aside><div class="shell"><header class="topbar">
    <nav class="academy-nav" aria-label="Navigasi akademi"><a href="/">Haikal Shiddiq</a><span>/</span><a href="/iasd">IASD</a><a href="/resources">Materi lain</a></nav>
    <div class="studio-tools"><button data-act="theme" aria-label="Ganti tema" aria-pressed="${document.documentElement.classList.contains('dark')}">Tema ${document.documentElement.classList.contains('dark')?'gelap':'terang'}</button><button data-act="focus">${focus?'Keluar mode tampil':'Mode tampil'}</button>
    <details class="tools-menu"><summary>Progres & alat</summary><div class="actions"><button data-act="overview">Peta progres</button><button data-act="export">Cadangan JSON</button><button data-act="import">Pulihkan</button><button data-act="report">Rekap CSV</button><button data-act="print">Cetak tampilan</button><p class="small">Data hanya pada browser ini. Ekspor sebelum pindah perangkat; tidak terkirim otomatis.</p></div></details></div>
    <label class="mobile-session" for="session-select">Pertemuan<select id="session-select">${C.lessons.map(x=>`<option value="${x.n}" ${view===x.n?'selected':''}>${String(x.n).padStart(2,'0')} · ${esc(x.title)}</option>`).join('')}</select></label>
  </header><div id="storage-warning" class="storage-warning" ${storageOK?'hidden':''}>Penyimpanan lokal tidak tersedia atau cadangan lokal tidak valid. Ekspor cadangan sebelum menutup modul.</div>
  <main id="main" class="content" tabindex="-1"><div id="lesson-content">${lessonHTML(item)}</div><footer class="copyright">Materi diadaptasi dari lampiran IASD versi ${C.version}. Klaim keselarasan akademik berasal dari lampiran; dokumen RPS asli belum disertakan untuk verifikasi. Bobot penilaian adalah usulan. UTS/UAS di sini latihan publik, bukan ujian resmi. Progres lokal tanpa kiriman otomatis; tautan sumber dan tools eksternal memerlukan internet.</footer></main></div></div><input id="import-file" type="file" accept="application/json,.json" hidden>`;
  renderSim();restoreFields();
}
function nav(query=''){let found=0;return C.lessons.map((x,i)=>{if(!(`${x.title} ${x.outcome} CPMK${x.cp}`).toLowerCase().includes(query.toLowerCase()))return'';found++;return `${[0,8].includes(i)?`<div class="group-label">${i===0?'SEBELUM UTS':'SETELAH UTS'}</div>`:''}<button class="lesson-nav ${i+1===view?'active':''}" data-go="${i+1}" ${i+1===view?'aria-current="page"':''}><span class="num">${String(i+1).padStart(2,'0')}</span><span>${esc(x.title)}</span>${rec(i+1).complete?'<span class="done-dot" aria-label="Latihan selesai">✓</span>':''}</button>`;}).join('')||'<p class="no-results">Topik tidak ditemukan. Coba kata lain.</p>';}
function lessonHTML(x){return `<div class="badge-row row"><span class="badge teal">${view===8?'UTS':view===16?'UAS':view<8?'Fondasi & persiapan UTS':'Pendalaman & persiapan UAS'}</span><span class="badge">Sesi ${view} dari 16</span><span class="badge gold">Bobot RPS ${x.weight}% · usulan</span></div><section class="hero"><div><div class="eyebrow">${C.id} / Pertemuan ${String(view).padStart(2,'0')}</div><h1>${esc(x.title)}</h1><p class="lead">${esc(x.hook)}</p></div>${heroArt()}</section><div class="outcome"><p class="small"><b>${x.cp?'CPMK'+x.cp:'CPMK1–'+(view===8?'3':'4')} → Sub-CPMK S${String(view).padStart(2,'0')}</b></p><p>${esc(x.outcome)}</p><span class="rps-note">Menurut lampiran: ${esc(C.status)} RPS asli belum disertakan untuk verifikasi.</span></div><div class="stats"><div class="stat"><b>${[8,16].includes(view)?'Ujian*':C.minutes+' mnt'}</b><span>${[8,16].includes(view)?'*Durasi resmi ditetapkan dosen':'Rundown kelas reguler'}</span></div><div class="stat"><b id="completed-count">${progress()} / 16</b><span>Sesi latihan mandiri selesai</span></div><div class="stat"><b id="quiz-count">${rec().checked?grade()+' / 3':'Belum'}</b><span>Cek konsep · bukan nilai resmi</span></div></div><nav class="tabnav" role="tablist" aria-label="Bagian pertemuan">${[['concept','01 Konsep & visual'],['lab','02 Persiapan & praktik'],['reflect','03 Bukti & cek individu'],['teach','04 Panduan dosen'],['sources','05 Sumber']].map(([id,t])=>`<button role="tab" id="tab-${id}" aria-controls="pane-${id}" aria-selected="${tab===id}" data-tab="${id}">${t}</button>`).join('')}</nav>${pane('concept',conceptHTML(x))}${pane('lab',labHTML(x))}${pane('reflect',reflectHTML(x))}${pane('teach',teachHTML(x)+`<section class="panel"><h3>Miskonsepsi, transfer & rubrik</h3><p><b>Miskonsepsi:</b> ${esc(x.pitfall)}</p><p><b>Pertanyaan transfer:</b> ${esc(x.transfer)}</p><p>Gunakan rubrik: ketepatan artefak 40%, penalaran 30%, transfer individu 20%, refleksi perbaikan 10%. Skala 0–4 membantu diagnosis, bukan penetapan nilai resmi.</p><button data-tab="reflect">Buka refleksi & rubrik lengkap</button></section>`)}${pane('sources',sourcesHTML(x))}<div class="lesson-footer"><button data-go="${view-1}" ${view===1?'disabled':''}>← Sesi sebelumnya</button><button data-go="${view+1}" class="btn-dark" ${view===16?'disabled':''}>Sesi berikutnya →</button></div>`;}
function pane(id,html){return `<section class="pane" id="pane-${id}" role="tabpanel" aria-labelledby="tab-${id}" ${id!==tab?'hidden':''}>${id==='reflect'?supplementHTML(id):''}${html}${['concept','teach'].includes(id)?supplementHTML(id):''}</section>`;}
function conceptHTML(x){return `<div class="section-head"><div><h2>Pahami, prediksi, lalu coba</h2><p class="muted">Baca tiga konsep. Prediksi hasil sebelum mengubah simulator.</p></div><span class="badge">Blok baca 10–15 menit</span></div><div class="concept-grid">${x.concepts.map((c,i)=>`<article class="concept"><span class="idx">KONSEP 0${i+1}</span><h3>${esc(c.title)}</h3><p>${esc(c.text)}</p></article>`).join('')}</div><div class="notice"><strong>Miskonsepsi yang diuji</strong><br>${esc(x.pitfall)}</div><section class="sim" aria-label="Simulator pertemuan"><div class="sim-head"><h2 id="sim-title">Laboratorium visual</h2><div class="row"><button data-act="svg">Unduh visual SVG</button><button data-act="simreset">Ulang simulasi</button></div></div><div class="sim-body"><div id="sim-controls" class="controls"></div><div id="sim-viz" class="viz" aria-live="polite"></div></div><div class="sim-task"><b>Tantangan transfer:</b> ${esc(x.transfer)}<br><span class="small">Catat hasil dan alasan pada bagian Bukti. Simulator menggunakan aturan serta data latihan yang dinyatakan, bukan mesin validasi lengkap atau layanan produksi.</span></div></section>`;}
function assetsFor(){return Object.keys(C.files).filter(name=>name!=='lembar_individu.csv');}
function labHTML(x){return `<div class="section-head"><div><h2>Praktik dengan hasil yang bisa diperiksa</h2><p class="muted">Satu portfolio berkembang sepanjang blok. Simpan alasan pribadi meskipun praktik dilakukan berpasangan.</p></div></div><div class="grid2"><section class="panel"><h3>Persiapan sebelum kelas</h3><p><b>Tools sesi:</b> ${esc(x.tool)}.</p><p>Baca kasus dan konsep selama 10–15 menit sebagai usulan prabaca. Siapkan browser, file latihan lokal, penyimpanan, dan akses RISE. Gunakan alias; hindari data rahasia kantor. Total beban belajar serta tenggat mengikuti ketetapan prodi.</p><p>Uji membuka dan menyimpan satu file. Saat koneksi atau akun gagal, jalankan simulator lokal dan tulis keputusan dengan bukti angka/diagram; lanjutkan file tools saat akses tersedia sesuai kesepakatan dosen.</p><p class="small">Aplikasi eksternal dan akun kampus perlu rehearsal. Menu dapat berbeda menurut bahasa, versi atau hak akses.</p></section><section class="panel"><h3>Kriteria keluaran sesi</h3>${x.criteria.map((t,i)=>`<div class="criterion"><b>0${i+1}</b><span>${esc(t)}</span></div>`).join('')}<p class="small"><b>Artefak RPS:</b> ${esc(x.evidence)}.</p></section></div><details class="panel materials"><summary>Bahan & tools: 13 berkas latihan</summary><p class="small">Seluruh bahan lampiran tersedia di website ini dan dapat diunduh tanpa akun. Rujukan serta tools eksternal ada di bagian Sumber dan memerlukan internet.</p><div class="resources">${assetsFor().map(n=>`<button data-file="${esc(n)}">↓ ${esc(n)}</button>`).join('')}<button data-file="lembar_individu.csv">↓ Lembar individu kosong</button></div></details><section class="panel"><h3>Langkah kerja sesi ${view}</h3><p class="small">Centang setelah dilakukan. Centang merupakan catatan pribadi dan perlu didukung file hasil.</p><ol class="steps">${x.steps.map((s,i)=>`<li class="step"><input type="checkbox" id="step-${i}" data-step="${i}" ${rec().checks[i]?'checked':''}><label for="step-${i}"><b>${String(i+1).padStart(2,'0')}</b>${esc(s)}</label></li>`).join('')}</ol></section><div class="notice"><b>Ritme mahasiswa bekerja</b><br>Kerjakan konsep → satu demo → satu artefak inti → cek individu. Saat belajar mandiri, pecah langkah menjadi blok 15–25 menit dan gunakan cadangan JSON untuk melanjutkan. Usulan remediasi memperbaiki artefak yang sama sehingga tidak menambah proyek baru.</div><button class="btn-primary" data-tab="reflect">Lanjut ke bukti pemahaman →</button>`;}
function reflectHTML(x){return `<div class="section-head"><div><h2>Jelaskan dengan kata-kata sendiri</h2><p class="muted">Kuis memberi feedback konsep. Jawaban terbuka dan file artefak perlu ditinjau dosen.</p></div><span class="badge">Individu · berbasis bukti</span></div><section class="panel"><label class="field">Alias belajar (opsional, tanpa identitas sensitif)<input id="alias" type="text" maxlength="80" value="${esc(state.alias)}" placeholder="Contoh: Mahasiswa-07"></label>${x.prompts.map((p,i)=>`<label class="field" for="note-${i}">${i+1}. ${esc(p)}<textarea id="note-${i}" data-note="${i}" maxlength="12000" placeholder="Tulis keputusan, alasan dan bukti Anda. Jawaban terbuka tidak dinilai otomatis.">${esc(rec().notes[i])}</textarea></label>`).join('')}<div class="row"><button data-act="worksheet" class="btn-primary">Unduh lembar kerja sesi (.txt)</button><button data-act="save">Simpan catatan</button></div><p class="focus-tip">Penyimpanan lokal bergantung browser dan lokasi file; cadangan JSON adalah cara pindah perangkat. Tidak ada pengumpulan otomatis ke dosen.</p></section><section class="panel quiz"><h3>Cek konsep · 3 pertanyaan</h3><p class="small">Jawab dulu, kemudian periksa. Ulang setelah membaca feedback. Skor latihan ini tidak masuk perhitungan bobot RPS.</p>${x.quiz.map((q,i)=>`<fieldset><legend>${i+1}. ${esc(q.prompt)}</legend>${q.options.map((a,j)=>`<label class="answer"><input type="radio" name="q${i}" data-question="${i}" value="${j}" ${rec().answers[i]===j?'checked':''}><span>${esc(a)}</span></label>`).join('')}${rec().checked?`<p class="question-feedback ${rec().answers[i]===q.answer?'correct':'incorrect'}">${rec().answers[i]===q.answer?'Tepat.':'Perlu ditinjau.'} ${esc(q.why)}</p>`:''}</fieldset>`).join('')}<div class="toolbar-bottom"><button data-act="grade" class="btn-primary">Periksa pemahaman</button><b id="grade-result">${rec().checked?grade()+' dari 3 tepat. Target latihan minimal 2/3; ulangi bagian yang belum dipahami.':''}</b></div></section><section class="panel"><h3>Rubrik latihan untuk penilaian diri</h3><p class="small">0 belum ada bukti · 1 banyak kesalahan · 2 cukup dengan bantuan · 3 benar mandiri · 4 benar, beralasan dan mampu menguji variasi. Ini refleksi diri; dosen memberi skor resmi pada bukti aktual.</p><div class="table-wrap"><table class="rubric"><thead><tr><th>Kriteria</th><th>Bobot dalam satu tugas</th><th>Refleksi diri 0–4</th></tr></thead><tbody>${[['Ketepatan artefak','40%'],['Penalaran','30%'],['Transfer individu','20%'],['Refleksi perbaikan','10%']].map(([t,w],i)=>`<tr><td>${t}</td><td>${w}</td><td><label><span class="hidden">Skor diri ${t}</span><input data-rubric="${i}" aria-label="Skor diri ${t}" type="number" min="0" max="4" step="1" value="${rec().rubric[i]}"></label></td></tr>`).join('')}</tbody></table></div><p id="rubric-result" class="small">${rubricText()}</p><p class="small">Usulan tugas kelompok: 70% artefak tim + 30% pembelaan individu. Komponen latihan di HTML tidak menambah bobot resmi.</p></section><section class="panel"><h3>Tutup sesi dengan bukti</h3><p>Untuk menandai latihan selesai: coba kontrol simulator, centang minimal enam langkah, isi tiga refleksi (masing-masing minimal 20 karakter), dan jawab minimal dua kuis dengan tepat. Ini pemeriksaan kelengkapan latihan, bukan pengesahan penguasaan CPMK.</p><div class="row"><button data-act="complete" class="btn-dark">Tandai latihan sesi selesai</button><span id="completion-status">${rec().complete?'✓ Selesai sebagai latihan mandiri.':'Belum ditandai selesai.'}</span></div><p class="small">Jika masih keliru, pilih satu miskonsepsi, perbaiki artefak yang sama, lalu jelaskan ulang pada dosen. Target usulan CPMK 75 perlu keputusan prodi dan bukan ambang kelulusan otomatis.</p></section>`;}
function rubricText(){const [a,b,c,d]=rec().rubric;return `Skor refleksi diri = 10A + 7,5B + 5C + 2,5D = ${fmt(10*a+7.5*b+5*c+2.5*d,1)}/100. Bukan nilai resmi.`;}
function teachHTML(x){const regular=C.id==='IASD'?[['0–10','Diagnosis dan tujuan'],['10–25','Konsep dan contoh salah'],['25–40','Demo visual/tools'],['40–75','Praktik berpasangan'],['75–100','Peer review dan walkthrough'],['100–125','Revisi dan transfer individu'],['125–135','Refleksi dan pengumpulan']]:[['0–8','Diagnosis dan prediksi'],['8–20','Konsep dan satu contoh hitung'],['20–32','Demo dari input ke output'],['32–60','Praktik dan perubahan asumsi'],['60–75','Diskusi bukti dan kesalahan'],['75–85','Kasus transfer individu'],['85–90','Exit ticket dan pengumpulan']];return `<div class="section-head"><div><h2>Pandu diskusi, periksa alasannya</h2><p class="muted">Panduan fasilitasi terbuka dari lampiran. Ketentuan akademik dan administrasi belum diverifikasi terhadap RPS asli. Tab ini tidak dilindungi kata sandi dan tidak menyimpan kunci ujian resmi.</p></div></div><section class="panel teaching"><h3>Alur penjelasan sesi ${view}</h3><ol><li>Mulai dengan pertanyaan: <b>${esc(x.hook)}</b> Minta prediksi individu sebelum diskusi.</li>${x.concepts.map(c=>`<li>Jelaskan <b>${esc(c.title)}</b> memakai kasus Aruna, kemudian minta mahasiswa menyebut satu konsekuensi praktis.</li>`).join('')}<li>Ubah satu kontrol simulator dan minta mahasiswa menjelaskan sebab hasil berubah. Tahan demo sampai prediksi mereka tercatat.</li><li>Jalankan langkah praktik. Tanyakan <b>${esc(x.prompts[1])}</b> kepada mahasiswa berbeda, termasuk yang tidak mengoperasikan tools.</li><li>Berikan variasi: <b>${esc(x.transfer)}</b> Nilai alasan dan bukti individual; catat miskonsepsi untuk perbaikan sesi berikutnya.</li></ol></section><div class="grid2"><section class="panel"><h3>Rencana slide sesi ini</h3><ol>${['Tujuan dan Sub-CPMK S'+String(view).padStart(2,'0'),x.hook,...x.concepts.map(c=>c.title),'Visual dan satu contoh salah','Instruksi praktikum dan artefak','Kasus transfer individu','Rubrik, batas bukti dan refleksi'].map(t=>`<li>${esc(t)}</li>`).join('')}</ol><p class="small">Mode tampil menyembunyikan sidebar untuk screen sharing; tampilan ini tetap HTML interaktif, bukan ekspor PPTX.</p></section><section class="panel"><h3>${[8,16].includes(view)?'Panduan sesi ujian':'Rundown reguler'}</h3>${[8,16].includes(view)?`<p class="exam-tag">Latihan publik dan panduan ${view===8?'UTS':'UAS'}</p><p>Siapkan varian kasus, instrumen dan kunci terpisah dari HTML. Tetapkan durasi dan bantuan sesuai ketentuan prodi. Lakukan briefing → pengerjaan individu → pembelaan sesuai instrumen → unggah → refleksi. Jangan menjadikan kuis publik ini ujian resmi.</p><p>Alokasi poin bobot: ${C.id==='IASD'?(view===8?'CPMK1 5; CPMK2 5; CPMK3 5.':'CPMK1 3; CPMK2 4; CPMK3 4; CPMK4 4.'):(view===8?'CPMK1 6; CPMK2 8; CPMK3 6.':'CPMK1 4; CPMK2 6; CPMK3 5; CPMK4 5.')}</p>`:`<div class="table-wrap"><table><thead><tr><th>Menit</th><th>Kegiatan</th></tr></thead><tbody>${regular.map(([t,s])=>`<tr><td>${t}</td><td>${s}</td></tr>`).join('')}</tbody></table></div><p class="small">Jumlah ${C.minutes} menit berdasarkan capture kelas Professional 45 menit/SKS. Sesi presentasi dapat memakai rekaman prabaca dan review bergilir sesuai jumlah tim; semua individu tetap mendapat cek yang setara.</p>`}<div class="row"><button data-act="timer" id="timer-btn">Mulai fokus 5 menit</button><button data-act="timerreset">Ulang</button><b id="clock" class="clock">${clockText()}</b></div><p class="focus-tip">Timer latihan dapat dijeda; tidak mengukur durasi ujian atau kehadiran.</p></section></div><section class="panel"><h3>Persiapan dan administrasi dosen</h3><p><b>H−7:</b> cocokkan tujuan, kontrak dan jadwal; unggah brief, rubrik serta materi prabaca di RISE. <b>H−1:</b> rehearsal file kosong, audio, share screen, akun mahasiswa dan pengumpulan; siapkan fallback lokal. <b>Sesudah kelas:</b> moderasi bukti, berikan feedback dan rekap CPMK; input nilai resmi melalui platform kampus sesuai hak akses.</p><p>RISE untuk materi/tugas/kuis/presensi dan TRACK untuk jadwal/komposisi/input nilai mengikuti capture yang diterima. Nama menu akun aktual belum diuji. Ketentuan presensi 75% versus sekitar 80%, kalender blok dan mekanisme ujian memerlukan penegasan akademik.</p><p><b>CQI:</b> catat miskonsepsi → periksa artefak → beri koreksi → minta transfer setara → nilai ulang sesuai kontrak → ukur pada kegiatan berikutnya. Jangan mengisi status perbaikan berhasil sebelum ada bukti.</p></section>`;}
function sourcesHTML(x){return `<h2>Sumber dan batas penggunaan</h2><p>Penelusuran terarah memakai dokumentasi primer yang relevan. Ini bukan klaim mengindeks seluruh internet. Konsep ditulis ulang dengan kasus dan visual orisinal; sebagian halaman aplikasi hanya dapat dibaca sebagai shell. Menurut lampiran, rujukan ditinjau 17 Oktober 2026; menu, lisensi dan akses dapat berubah.</p><h3>Rujukan sesi ${view}</h3><ol class="source-list">${x.refs.map(sourceHTML).join('')}</ol><details><summary>Seluruh rujukan modul ini (${Object.keys(C.sources).length})</summary><ol class="source-list">${Object.keys(C.sources).map(sourceHTML).join('')}</ol></details><section class="panel"><h3>Keselarasan akademik</h3><p>${esc(C.status)}</p><p>${esc(C.outcomes[0])}</p><p>${esc(C.outcomes[1])}</p><p class="small">Menurut lampiran HTML, dasar akademiknya adalah ${esc(C.rps.name)}. Dokumen RPS asli tidak disertakan; klaim keselarasan 16 Sub-CPMK dan bobot sesi merupakan keterangan lampiran, bukan verifikasi baru website. Jadwal 8 minggu dengan dua sesi per minggu merupakan peta usulan; tanggal aktual mengikuti prodi.</p><p class="small">${C.id==='IASD'?'Menurut lampiran, prodi pada RPS yang dirujuk adalah Sistem Informasi; capture penugasan disebut memakai Sistem dan Teknologi Informasi. Dokumen dan capture asli belum disertakan untuk verifikasi website. Kode SI306 dan Teori 1/Praktikum 2 dipertahankan. Bobot tabel sesi 15% untuk UTS/UAS berbeda dari ringkasan default 25%; usulan mengikuti tabel sesi sampai prodi menetapkan.':'Kode MK, CPL resmi dan pembagian teori/praktik tidak direka dari identitas IASD. Bobot dan capaian tetap usulan sampai diselaraskan dengan kurikulum finance.'}</p></section><section class="panel"><h3>Privasi dan penyimpanan</h3><p>Progres disimpan hanya pada browser/perangkat jika didukung. File tidak mengirim jawaban atau membuka tautan otomatis. Gunakan Cadangan JSON sebelum pindah perangkat, mengganti nama/lokasi file atau membersihkan browser. Pulihkan hanya berkas milik mata kuliah dan versi ini. File lokal dapat diedit pengguna; data ekspor dan status selesai bukan bukti penilaian resmi.</p></section>`;}
function sourceHTML(id){const s=C.sources[id];return s?`<li><a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">${esc(s.title)} ↗</a><p>${esc(s.use)} · Ditinjau ${s.checked}</p></li>`:'';}
function overview(){tab='overview';$('#lesson-content').innerHTML=`<div class="hero"><div><div class="eyebrow">Studio belajar Professional · ${C.sks} SKS</div><h1>${C.title}</h1><p class="lead">Dari pemahaman konsep ke keputusan yang dapat Anda jelaskan dan buktikan.</p><span class="badge gold">${C.id==='AIF'?'Usulan pengampu · RPS finance belum tersedia':'Materi lampiran · RPS asli belum diverifikasi'}</span></div>${heroArt()}</div><div class="grid2"><section class="panel"><h2>Mulai dalam empat langkah</h2><ol><li>Pilih pertemuan. Baca tiga konsep dan prediksi hasil visual.</li><li>Ubah kontrol simulator, lalu kerjakan langkah praktik dengan file yang sudah dibundel.</li><li>Tulis tiga refleksi individu, jawab kuis dan simpan artefak asli.</li><li>Unduh lembar kerja untuk RISE dan cadangan JSON untuk melanjutkan.</li></ol><p class="small">Untuk mahasiswa bekerja: blok baca 10–15 menit, lanjutkan kerja dalam blok 15–25 menit. Waktu prabaca adalah usulan; tenggat dan beban resmi mengikuti pengampu.</p></section><section class="panel"><h2>Terukur tanpa mencampur nilai</h2><div class="callout-num">${progress()} / 16</div><p>Sesi latihan ditandai selesai. Kuis, centang dan rubrik diri membantu diagnosis; dosen memeriksa file serta alasan sebelum memberi nilai resmi.</p><p class="small">UTS/UAS pada file ini adalah latihan publik dan panduan. Soal resmi beserta kunci disiapkan terpisah. HTML tidak memiliki proctoring, autentikasi atau pengumpulan otomatis.</p><p class="small">Ekspor rekap CSV memuat status dan skor latihan, bukan bobot nilai akhir. Jangan mengimpor rekap ini sebagai nilai resmi tanpa penilaian dosen.</p></section></div><h2 class="dashboard-head">Peta 16 pertemuan</h2><div class="map-grid">${C.lessons.map(x=>`<button class="map-item" data-go="${x.n}"><small>S${String(x.n).padStart(2,'0')} · ${x.cp?'CPMK'+x.cp:'Ujian integrasi'}</small><b>${esc(x.title)}</b><p>${x.weight}% bobot usulan · ${rec(x.n).complete?'✓ latihan selesai':'latihan belum selesai'}</p></button>`).join('')}</div><section class="panel"><h2>Ringkasan ketercapaian latihan per CPMK</h2><p class="small">Menghitung sesi primer yang ditandai selesai, bukan skor ketercapaian CPMK resmi. Ujian integrasi tetap ditinjau per bagian oleh dosen.</p>${[1,2,3,4].map(cp=>{const a=C.lessons.filter(x=>x.cp===cp),done=a.filter(x=>rec(x.n).complete).length;return `<div style="margin:16px 0"><b>CPMK${cp}: ${done}/${a.length} sesi primer</b><div class="meter"><div style="width:${done/a.length*100}%"></div></div></div>`}).join('')}</section><p class="small">${esc(C.status)} Modul dan rujukan ditinjau 17 Oktober 2026.</p>`;}
function go(n){if(!Number.isInteger(n)||n<1||n>C.lessons.length)return;view=n;tab=instructorMode?'teach':'concept';location.hash=n;app();$('#main').focus({preventScroll:true});window.scrollTo({top:0,behavior:'instant'});}
function setTab(t){if(!['concept','lab','reflect','teach','sources'].includes(t))return;if(tab==='overview'){tab=t;app();}else{tab=t;document.querySelectorAll('[role=tab]').forEach(b=>b.setAttribute('aria-selected',String(b.dataset.tab===t)));document.querySelectorAll('.pane').forEach(p=>p.hidden=p.id!=='pane-'+t);}$('#tab-'+t)?.focus({preventScroll:true});}
function restoreFields(){} // Values are escaped into the markup on every navigation.
function clockText(){return String(Math.floor(seconds/60)).padStart(2,'0')+':'+String(seconds%60).padStart(2,'0');}
function updateClock(){if($('#clock'))$('#clock').textContent=clockText();if($('#timer-btn'))$('#timer-btn').textContent=timer?'Jeda timer':'Mulai / lanjut fokus';}
function worksheet(){const r=rec(),x=l();const txt=[C.title+' · '+C.sks+' SKS','Sesi '+view+' — '+x.title,'Alias: '+(state.alias||'(belum diisi)'), 'Sub-CPMK: '+x.outcome,'Status: '+(r.complete?'Latihan mandiri selesai':'Belum selesai')+'; bukan nilai resmi','Artefak RPS: '+x.evidence,...x.prompts.flatMap((p,i)=>['\n'+(i+1)+'. '+p,r.notes[i]||'(belum diisi)']), '\nKuis latihan: '+(r.checked?grade()+'/3':'belum diperiksa'),'Langkah dicentang: '+Object.values(r.checks).filter(Boolean).length+'/'+x.steps.length,'Simulasi: '+JSON.stringify(r.sim),'\nLampiran artefak asli: (isi nama file/link setelah disiapkan)','Deklarasi bantuan dan sumber: (isi sendiri)','Refleksi diri: '+rubricText(),'\nUnggah sendiri ke kanal RISE sesuai instruksi dosen. Tidak terkirim otomatis.'].join('\n');download(C.id+'_S'+String(view).padStart(2,'0')+'_Lembar_Individu.txt',txt);}
function report(){const cell=v=>{let s=String(v??'');if(/^[=+\-@\t\r]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"';};let rows=[['mata_kuliah','alias','sesi','CPMK_primer','Sub_CPMK','bobot_RPS_usulan','kuis_latihan_benar_dari_3','langkah_dicentang','refleksi_terisi','simulator_dicoba','latihan_selesai','jenis_data']];for(const x of C.lessons){const r=rec(x.n);rows.push([C.id,state.alias,x.n,x.cp||'ujian_integrasi',x.outcome,x.weight,r.checked?grade(x.n):'',Object.values(r.checks).filter(Boolean).length,r.notes.filter(s=>s.trim().length>=20).length,r.used?'ya':'belum',r.complete?'ya':'belum','LATIHAN_MANDIRI_BUKAN_NILAI_RESMI']);}download(C.id+'_Rekap_Latihan.csv','\ufeff'+rows.map(r=>r.map(cell).join(',')).join('\r\n'),'text/csv;charset=utf-8');}
document.addEventListener('input',e=>{const t=e.target;if(t.id==='search'){$('#lesson-list').innerHTML=nav(t.value);return;}if(t.id==='alias'){state.alias=t.value;save();return;}if(t.dataset.note!==undefined){rec().notes[Number(t.dataset.note)]=t.value;rec().complete=false;save();}if(t.dataset.setting&&t.type==='range'){const out=document.getElementById('value-'+t.dataset.setting);if(out)out.textContent=t.value;}});
document.addEventListener('change',async e=>{const t=e.target,r=rec();if(t.dataset.step!==undefined){r.checks[t.dataset.step]=t.checked;r.complete=false;save();}if(t.dataset.question!==undefined){r.answers[t.dataset.question]=Number(t.value);r.checked=false;r.complete=false;save();$('#grade-result').textContent='Jawaban berubah; periksa kembali.';document.querySelectorAll('.question-feedback').forEach(x=>x.remove());$('#quiz-count').textContent='Belum';}if(t.dataset.rubric!==undefined){const v=Math.max(0,Math.min(4,Math.round(Number(t.value)||0)));t.value=v;r.rubric[Number(t.dataset.rubric)]=v;save();$('#rubric-result').textContent=rubricText();}if(t.dataset.setting){r.sim[t.dataset.setting]=t.type==='checkbox'?t.checked:t.type==='number'||t.type==='range'?Number(t.value):t.value;r.used=true;r.complete=false;save();renderSim();}if(t.id==='import-file'&&t.files[0]){try{if(t.files[0].size>3000000)throw Error('Berkas terlalu besar.');const next=validateState(JSON.parse(await t.files[0].text()));if(Object.keys(state.lessons).length&& !confirm('Pulihkan cadangan dan ganti progres lokal mata kuliah ini? Ekspor cadangan saat ini bila masih dibutuhkan.'))return;state=next;save();app();toast('Cadangan dipulihkan untuk '+C.id+'.');}catch(err){toast('Tidak dipulihkan: '+err.message);}finally{t.value='';$('.tools-menu summary')?.focus({preventScroll:true});}}});
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||b.disabled)return;if(b.dataset.go){go(Number(b.dataset.go));return;}if(b.dataset.tab){setTab(b.dataset.tab);return;}if(b.dataset.file){download(b.dataset.file,C.files[b.dataset.file]);return;}if(b.dataset.simact){simAction(b.dataset.simact,b.dataset.value);return;}switch(b.dataset.act){case'overview':overview();break;case'focus':focus=!focus;document.body.classList.toggle('fullfocus',focus);b.textContent=focus?'Keluar mode tampil':'Mode tampil';break;case'export':download(C.id+'_Cadangan_Progres.json',JSON.stringify(state,null,2),'application/json');break;case'import':$('#import-file').click();break;case'report':report();break;case'print':window.print();break;case'worksheet':worksheet();break;case'save':save();toast(storageOK?'Catatan disimpan pada browser ini. Ekspor JSON untuk cadangan.':'Catatan ada sementara; ekspor JSON sebelum menutup.');break;case'grade':{if(Object.keys(rec().answers).length<3){toast('Jawab ketiga pertanyaan sebelum diperiksa.');return;}rec().checked=true;save();$('#pane-reflect').innerHTML=supplementHTML('reflect')+reflectHTML(l());$('[data-act=grade]').focus({preventScroll:true});$('#quiz-count').textContent=grade()+' / 3';toast(grade()>=2?'Cek konsep cukup. Tetap sertakan alasan dan artefak.':'Baca feedback, ulang visual lalu coba kembali.');break;}case'complete':{const r=rec();const errors=[];if(!r.used)errors.push('coba satu kontrol simulator');if(Object.values(r.checks).filter(Boolean).length<6)errors.push('centang minimal enam langkah praktik');if(r.notes.some(n=>n.trim().length<20))errors.push('isi tiga refleksi minimal 20 karakter');if(!r.checked||grade()<2)errors.push('periksa kuis dan capai minimal dua jawaban tepat');if(errors.length){toast('Belum lengkap: '+errors.join('; ')+'.');return;}r.complete=true;save();$('#completion-status').textContent='✓ Selesai sebagai latihan mandiri.';$('#completed-count').textContent=progress()+' / 16';$('#lesson-list').innerHTML=nav($('#search').value);toast('Sesi ditandai selesai. Penilaian resmi tetap oleh dosen.');break;}case'svg':{const v=$('#sim-viz svg');if(v){const copy=v.cloneNode(true);copy.setAttribute('xmlns','http://www.w3.org/2000/svg');copy.insertAdjacentHTML('afterbegin','<style>text{font-family:sans-serif;fill:#173d50}</style>');download(C.id+'_S'+view+'_Visual.svg',new XMLSerializer().serializeToString(copy),'image/svg+xml');}else toast('Layar prototipe dapat dicetak melalui Cetak tampilan.');break;}case'simreset':rec().sim={};rec().used=false;rec().complete=false;save();renderSim();toast('Simulator sesi diulang; refleksi dan kuis tetap tersimpan.');break;case'timer':if(timer){clearInterval(timer);timer=null;}else{if(seconds<=0)seconds=300;timer=setInterval(()=>{seconds--;updateClock();if(seconds<=0){clearInterval(timer);timer=null;updateClock();toast('Blok fokus selesai. Catat satu hal yang Anda pahami.');}},1000);}updateClock();break;case'timerreset':clearInterval(timer);timer=null;seconds=300;updateClock();break;}});
function svgw(content,label,w=760,h=280){return `<svg viewBox="0 0 ${w} ${h}" role="img" aria-label="${esc(label)}"><title>${esc(label)}</title><defs><marker id="arr" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="6" markerHeight="6" orient="auto-start-reverse"><path d="M0 0L10 5L0 10z" fill="#567d8c"/></marker></defs>${content}</svg>`;}
function textSVG(x,y,s,size=15,anchor='middle',color='#173d50'){return `<text x="${x}" y="${y}" text-anchor="${anchor}" font-size="${size}" style="fill:${color}">${esc(s)}</text>`;}
function wrapLabel(s,max=19){const words=String(s).split(' '),lines=[''];for(const w of words){if((lines.at(-1)+' '+w).trim().length>max)lines.push(w);else lines[lines.length-1]=(lines.at(-1)+' '+w).trim();}return lines;}
function boxSVG(x,y,w,h,label,active=false,type='box'){let shape;const fill=active?'#d1ece6':'#fff',stroke=active?'#087e80':'#a8bec7';if(type==='diamond')shape=`<path d="M${x+w/2} ${y}L${x+w} ${y+h/2}L${x+w/2} ${y+h}L${x} ${y+h/2}Z" fill="${fill}" stroke="${stroke}" stroke-width="2"/>`;else if(type==='circle')shape=`<circle cx="${x+w/2}" cy="${y+h/2}" r="${Math.min(w,h)/2-3}" fill="${fill}" stroke="${stroke}" stroke-width="2"/>`;else shape=`<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="${type==='state'?20:9}" fill="${fill}" stroke="${stroke}" stroke-width="2"/>`;const lines=wrapLabel(label,type==='diamond'?13:18);return shape+lines.map((s,i)=>textSVG(x+w/2,y+h/2-(lines.length-1)*9+i*19+5,s,14)).join('');}
function flow(labels,active=-1,types=[]){const w=760,gap=12,sz=(720-gap*(labels.length-1))/labels.length;return svgw(labels.map((s,i)=>`${i?`<line x1="${20+(i-1)*(sz+gap)+sz}" y1="92" x2="${20+i*(sz+gap)}" y2="92" stroke="#567d8c" stroke-width="2" marker-end="url(#arr)"/>`:''}${boxSVG(20+i*(sz+gap),55,sz,75,s,i===active,types[i]||'box')}`).join(''),'Alur '+labels.join(' menuju '),w,190);}
function feedback(t,kind=''){return `<div class="feedback ${kind}">${t}</div>`;}
function metric(v,label){return `<div class="metric"><b>${esc(v)}</b><span>${esc(label)}</span></div>`;}
function table(headers,rows){return `<div class="table-wrap"><table><thead><tr>${headers.map(x=>`<th>${esc(x)}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr>${row.map(x=>`<td>${esc(x)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;}
function selectControl(key,label,choices,value){return `<label>${esc(label)}<select data-setting="${key}" id="control-${key}">${choices.map(c=>{const[k,v]=Array.isArray(c)?c:[c,c];return`<option value="${esc(k)}" ${String(value)===String(k)?'selected':''}>${esc(v)}</option>`}).join('')}</select></label>`;}
function rangeControl(key,label,min,max,step,value){return `<label for="control-${key}">${esc(label)}<span id="value-${key}">${esc(value)}</span><input type="range" id="control-${key}" data-setting="${key}" min="${min}" max="${max}" step="${step}" value="${value}"></label>`;}
function checkControl(key,label,value){return `<label class="check"><input type="checkbox" data-setting="${key}" ${value?'checked':''}><span>${esc(label)}</span></label>`;}
function simButton(action,label,value=''){return `<button data-simact="${action}" data-value="${esc(value)}">${esc(label)}</button>`;}
